<?php
require __DIR__.'/../bootstrap.php';
require_login();
$cu=current_user();
$db=db();
ensure_file_workspace_schema();
$uid=(int)$cu['id'];
$msg='';$msgType='info';

function media_kind(string $mime,string $name):string{
    $m=strtolower($mime);$n=strtolower($name);
    if(str_starts_with($m,'image/'))return'image';
    if(str_starts_with($m,'audio/'))return'audio';
    if(str_starts_with($m,'video/'))return'video';
    if($m==='application/zip'||str_ends_with($n,'.zip'))return'archive';
    return'file';
}
function media_clean_folder(string $v):string{
    $v=trim(str_replace('\\','/',$v));
    $v=preg_replace('/[^A-Za-z0-9._\/-]+/','-',substr($v,0,180));
    $v=trim((string)$v," /.-");
    return $v!==''?$v:'General';
}
function media_clean_name(string $v):string{return trim(mb_substr(basename(str_replace('\\','/',$v)),0,180));}
function media_user_folder_exists(PDO $db,int $uid,string $folder):bool{
    $q=$db->prepare('SELECT 1 FROM media_assets WHERE user_id=? AND folder_name=? LIMIT 1');$q->execute([$uid,$folder]);return(bool)$q->fetchColumn();
}
function media_scope_ids(array $ids):array{return array_values(array_unique(array_filter(array_map('intval',$ids),fn($v)=>$v>0)));}

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $a=(string)post('action');
    try{
        if($a==='create_folder'){
            $folder=media_clean_folder((string)post('folder'));
            if(media_user_folder_exists($db,$uid,$folder)){$msg='That folder already exists.';$msgType='error';}
            else{
                $db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_url,mime_type,size_bytes,kind,auto_fit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,NOW(),NOW())')
                   ->execute([$uid,'.folder-marker',$folder,'url','about:blank','application/x-folder-marker',0,'file']);
                $msg='Folder created: '.$folder;
            }
        } elseif($a==='rename_folder'){
            $old=media_clean_folder((string)post('old_folder'));$new=media_clean_folder((string)post('new_folder'));
            if($old===$new){$msg='No folder name change was made.';}
            elseif(!media_user_folder_exists($db,$uid,$old)){$msg='Folder not found.';$msgType='error';}
            elseif(media_user_folder_exists($db,$uid,$new)){$msg='A folder with that name already exists.';$msgType='error';}
            else{
                $q=$db->prepare('UPDATE media_assets SET folder_name=?,updated_at=NOW() WHERE user_id=? AND folder_name=?');$q->execute([$new,$uid,$old]);
                $msg='Folder renamed. '.$q->rowCount().' asset(s) updated.';
            }
        } elseif($a==='delete_folder'){
            $folder=media_clean_folder((string)post('folder'));
            $q=$db->prepare('SELECT COUNT(*) FROM media_assets WHERE user_id=? AND folder_name=? AND name<>?');$q->execute([$uid,$folder,'.folder-marker']);
            if((int)$q->fetchColumn()>0){$msg='Folder is not empty. Move or delete its assets first.';$msgType='error';}
            else{$db->prepare('DELETE FROM media_assets WHERE user_id=? AND folder_name=? AND name=?')->execute([$uid,$folder,'.folder-marker']);$msg='Folder deleted: '.$folder;}
        } elseif($a==='upload' && !empty($_FILES['media']['tmp_name'])){
            $fs=$_FILES['media'];
            $tmp=is_array($fs['tmp_name'])?$fs['tmp_name']:[$fs['tmp_name']];
            $names=is_array($fs['name'])?$fs['name']:[$fs['name']];
            $sizes=is_array($fs['size'])?$fs['size']:[$fs['size']];
            $errors=is_array($fs['error'])?$fs['error']:[$fs['error']];
            $paths=is_array($fs['full_path']??null)?$fs['full_path']:[];
            $folder=media_clean_folder((string)post('folder','General'));
            if(!media_user_folder_exists($db,$uid,$folder)){
                $db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_url,mime_type,size_bytes,kind,auto_fit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([$uid,'.folder-marker',$folder,'url','about:blank','application/x-folder-marker',0,'file']);
            }
            $dir=__DIR__.'/../uploads/media/'.$uid;
            if(!is_dir($dir) && !@mkdir($dir,0750,true) && !is_dir($dir))throw new RuntimeException('Media upload directory could not be created. Check server write permissions.');
            $ok=0;$skipped=0;$skipReasons=[];
            foreach($tmp as $i=>$tp){
                $err=(int)($errors[$i]??UPLOAD_ERR_NO_FILE);
                if($err!==UPLOAD_ERR_OK || !is_uploaded_file($tp)){$skipped++;$skipReasons[]='invalid upload';continue;}
                $size=(int)($sizes[$i]??0);
                if($size<=0){$skipped++;$skipReasons[]='empty file';continue;}
                if($size>file_local_max_bytes()){$skipped++;$skipReasons[]='over the current PHP upload limit';continue;}
                $name=media_clean_name((string)($names[$i]??''));if($name===''){$skipped++;$skipReasons[]='invalid filename';continue;}
                $relative=trim((string)($paths[$i]??''));
                if($relative!==''){
                    $relative=str_replace('\\','/',$relative);
                    $segments=array_values(array_filter(explode('/',$relative),fn($x)=>$x!==''&&$x!=='.'&&$x!=='..'));
                    if(count($segments)>1){$dirName=media_clean_folder(implode('/',array_slice($segments,0,-1)));if($dirName!=='General')$folderForFile=$folder.'/'.$dirName;else $folderForFile=$folder;}else{$folderForFile=$folder;}
                }else{$folderForFile=$folder;}
                if(!media_user_folder_exists($db,$uid,$folderForFile)){
                    $db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_url,mime_type,size_bytes,kind,auto_fit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([$uid,'.folder-marker',$folderForFile,'url','about:blank','application/x-folder-marker',0,'file']);
                }
                $mime=function_exists('mime_content_type')?(mime_content_type($tp)?:'application/octet-stream'):(string)($fs['type'][$i]??'application/octet-stream');if(function_exists('file_blacklisted')&&file_blacklisted($name,$mime)){$skipped++;$skipReasons[]='blocked file type';continue;}
                $kind=media_kind($mime,$name);$ext=pathinfo($name,PATHINFO_EXTENSION);$safeExt=$ext?'.'.preg_replace('/[^a-zA-Z0-9]+/','',$ext):'';
                $file=bin2hex(random_bytes(16)).$safeExt;$path=$dir.'/'.$file;
                if(!@move_uploaded_file($tp,$path) && !@copy($tp,$path)){$skipped++;$skipReasons[]='server could not write file';continue;}
                $url='/uploads/media/'.$uid.'/'.$file;$w=null;$h=null;
                if($kind==='image'){$info=@getimagesize($path);$w=$info[0]??null;$h=$info[1]??null;}
                $created=file_create_from_media_upload(['path'=>$path,'url'=>$url,'name'=>$name,'mime'=>$mime,'size'=>$size,'relative_path'=>$relative],$uid,$folderForFile);$hash=hash_file('sha256',$path);$db->prepare('UPDATE media_assets SET content_sha256=? WHERE id=? AND user_id=?')->execute([$hash,(int)$created['id'],$uid]);$ok++;
            }
            $msg=$ok?'Uploaded '.$ok.' asset(s).':'No files were uploaded.';
            if($skipped){$msg.=' '.$skipped.' file(s) were skipped.';if($skipReasons)$msg.=' '.implode(', ',array_slice(array_unique($skipReasons),0,3)).'.';}
        } elseif($a==='url'){
            $url=trim((string)post('source_url'));$name=media_clean_name((string)post('name','Remote media'));$folder=media_clean_folder((string)post('folder','General'));$mime=trim((string)post('mime_type','application/octet-stream'));
            if(!filter_var($url,FILTER_VALIDATE_URL)||!preg_match('~^https?://~i',$url)){$msg='Only valid HTTP/HTTPS public URLs are allowed.';$msgType='error';}
