            else{
                if(!media_user_folder_exists($db,$uid,$folder))$db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_url,mime_type,size_bytes,kind,auto_fit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([$uid,'.folder-marker',$folder,'url','about:blank','application/x-folder-marker',0,'file']);
                $db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_category,source_ref_id,source_url,mime_type,size_bytes,kind,auto_fit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([$uid,$name,$folder,'url','Media Assets',0,$url,$mime,0,media_kind($mime,$name)]);$mediaId=(int)$db->lastInsertId();$db->prepare('UPDATE media_assets SET source_ref_id=? WHERE id=? AND user_id=?')->execute([$mediaId,$mediaId,$uid]);
                $msg='Public media URL saved.';
            }
        } elseif($a==='edit'){
            $id=(int)post('id');$name=media_clean_name((string)post('name'));$folder=media_clean_folder((string)post('folder'));$alt=trim((string)post('alt_text'));$desc=trim((string)post('description'));$fav=!empty($_POST['is_favorite'])?1:0;
            if($id>0&&$name!==''){
                if(!media_user_folder_exists($db,$uid,$folder))$db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_url,mime_type,size_bytes,kind,auto_fit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([$uid,'.folder-marker',$folder,'url','about:blank','application/x-folder-marker',0,'file']);
                $q=$db->prepare('UPDATE media_assets SET name=?,folder_name=?,alt_text=?,description=?,is_favorite=?,updated_at=NOW() WHERE id=? AND user_id=? AND name<>?');$q->execute([$name,$folder,mb_substr($alt,0,500),mb_substr($desc,0,2000),$fav,$id,$uid,'.folder-marker']);$msg=$q->rowCount()?'Media details saved.':'Media item not found.';$msgType=$q->rowCount()?'info':'error';
            }else{$msg='Could not save media details.';$msgType='error';}
        } elseif($a==='favorite'){
            $id=(int)post('id');$q=$db->prepare('UPDATE media_assets SET is_favorite=1-is_favorite,updated_at=NOW() WHERE id=? AND user_id=? AND name<>?');$q->execute([$id,$uid,'.folder-marker']);$msg=$q->rowCount()?'Favorite status updated.':'Media item not found.';$msgType=$q->rowCount()?'info':'error';
        } elseif(in_array($a,['bulk_move','bulk_copy'],true)){
            $ids=media_scope_ids((array)post('ids',[]));$folder=media_clean_folder((string)post('target_folder','General'));$mode=(string)post('conflict_mode','cancel');
            if(!in_array($mode,['cancel','skip','replace','rename'],true))$mode='cancel';
            if(!$ids){$msg='Select at least one media item.';$msgType='error';}
            elseif($folder==='General'||media_user_folder_exists($db,$uid,$folder)){
                $ph=implode(',',array_fill(0,count($ids),'?'));$q=$db->prepare("SELECT * FROM media_assets WHERE user_id=? AND name<>'.folder-marker' AND id IN ($ph) ORDER BY id");$q->execute(array_merge([$uid],$ids));$selected=$q->fetchAll();$changed=0;$skipped=0;$db->beginTransaction();
                try{foreach($selected as $item){$name=(string)$item['name'];$targetFolder=$folder;$find=$db->prepare("SELECT id FROM media_assets WHERE user_id=? AND folder_name=? AND name=? AND name<>'.folder-marker' LIMIT 1");$find->execute([$uid,$targetFolder,$name]);$duplicate=(int)($find->fetchColumn()?:0);if($a==='bulk_move'&&$item['folder_name']===$targetFolder)$duplicate=0;
                    if($duplicate){if($mode==='cancel')throw new RuntimeException('Duplicate names exist. Choose Skip duplicates, Replace, or Rename automatically.');if($mode==='skip'){$skipped++;continue;}if($mode==='replace'){$db->prepare('DELETE FROM media_assets WHERE id=? AND user_id=?')->execute([$duplicate,$uid]);}elseif($mode==='rename'){$base=pathinfo($name,PATHINFO_FILENAME);$ext=pathinfo($name,PATHINFO_EXTENSION);$n=1;do{$newName=$base.' ('.$n.')'.($ext!==''?'.'.$ext:'');$find->execute([$uid,$targetFolder,$newName]);$exists=$find->fetchColumn();$n++;}while($exists&&$n<10000);$name=$newName;}}
                    if($a==='bulk_move'){$u=$db->prepare('UPDATE media_assets SET name=?,folder_name=?,updated_at=NOW() WHERE id=? AND user_id=?');$u->execute([$name,$targetFolder,(int)$item['id'],$uid]);}
                    else{$db->prepare('INSERT INTO media_assets(user_id,name,folder_name,source_type,source_category,source_ref_id,source_url,storage_path,mime_type,size_bytes,kind,width,height,auto_fit,is_favorite,alt_text,description,canonical_file_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute([$uid,$name,$targetFolder,$item['source_type'],$item['source_category'],$item['source_ref_id'],$item['source_url'],$item['storage_path'],$item['mime_type'],$item['size_bytes'],$item['kind'],$item['width'],$item['height'],$item['auto_fit'],$item['is_favorite'],$item['alt_text'],$item['description'],$item['canonical_file_id']]);}
                    $changed++;}
                  $db->commit();$msg=($a==='bulk_move'?'Moved ':'Copied ').$changed.' item(s) to '.$folder.'.'.($skipped?' Skipped '.$skipped.' duplicate(s).':'');
                }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$msg=$e->getMessage();$msgType='error';}
            }else{$msg='Target folder does not exist.';$msgType='error';}
        } elseif($a==='bulk_delete'){
            $ids=media_scope_ids((array)post('ids',[]));
            if(!$ids){$msg='Select at least one media item.';$msgType='error';}
            else{$ph=implode(',',array_fill(0,count($ids),'?'));$q=$db->prepare("UPDATE media_assets SET deleted_at=NOW(),deleted_by=?,updated_at=NOW() WHERE user_id=? AND name<>'.folder-marker' AND deleted_at IS NULL AND id IN ($ph)");$q->execute(array_merge([$uid,$uid],$ids));$changed=$q->rowCount();if($changed)$db->prepare("INSERT INTO media_audit_events(user_id,action,resource_type,metadata_json,created_at) VALUES(?,?,?,?,NOW())")->execute([$uid,'TRASH','media',json_encode(['count'=>$changed])]);$msg='Moved '.$changed.' asset(s) to Trash. You can restore them for up to 30 days.';}
        } elseif($a==='delete'){
            $id=(int)post('id');$q=$db->prepare("UPDATE media_assets SET deleted_at=NOW(),deleted_by=?,updated_at=NOW() WHERE id=? AND user_id=? AND name<>'.folder-marker' AND deleted_at IS NULL");$q->execute([$uid,$id,$uid]);
            if(!$q->rowCount()){$msg='Media item not found.';$msgType='error';}else{$db->prepare("INSERT INTO media_audit_events(user_id,action,resource_type,resource_id,created_at) VALUES(?,?,?,?,NOW())")->execute([$uid,'TRASH','media',$id]);$msg='Media moved to Trash. Restore it any time within the retention period.';}
        } elseif($a==='bulk_restore'){
            $ids=media_scope_ids((array)post('ids',[]));if(!$ids){$msg='Select at least one trashed item.';$msgType='error';}else{$restored=0;$skipped=0;foreach($ids as $id){$it=$db->prepare('SELECT folder_name,name FROM media_assets WHERE id=? AND user_id=? AND deleted_at IS NOT NULL AND name<>?');$it->execute([$id,$uid,'.folder-marker']);$item=$it->fetch();if(!$item){$skipped++;continue;}$cf=$db->prepare('SELECT 1 FROM media_assets WHERE user_id=? AND folder_name=? AND name=? AND deleted_at IS NULL AND id<>? LIMIT 1');$cf->execute([$uid,$item['folder_name'],$item['name'],$id]);if($cf->fetchColumn()){$skipped++;continue;}$up=$db->prepare('UPDATE media_assets SET deleted_at=NULL,deleted_by=NULL,updated_at=NOW() WHERE id=? AND user_id=? AND deleted_at IS NOT NULL');$up->execute([$id,$uid]);if($up->rowCount()){$restored++;$db->prepare("INSERT INTO media_audit_events(user_id,action,resource_type,resource_id,created_at) VALUES(?,?,?,?,NOW())")->execute([$uid,'RESTORE','media',$id]);}}$msg='Restored '.$restored.' item(s).'.($skipped?' '.$skipped.' item(s) skipped because of missing items or name conflicts.':'');}
        } elseif($a==='restore'){
            $id=(int)post('id');$itemQ=$db->prepare('SELECT folder_name,name FROM media_assets WHERE id=? AND user_id=? AND deleted_at IS NOT NULL AND name<>?');$itemQ->execute([$id,$uid,'.folder-marker']);$item=$itemQ->fetch();if(!$item){$msg='Trashed item not found.';$msgType='error';}else{$conflict=$db->prepare('SELECT id FROM media_assets WHERE user_id=? AND folder_name=? AND name=? AND deleted_at IS NULL AND id<>? LIMIT 1');$conflict->execute([$uid,$item['folder_name'],$item['name'],$id]);if($conflict->fetchColumn()){$msg='Cannot restore because another active item has the same name in the original folder. Rename or move the active item first.';$msgType='error';}else{$q=$db->prepare('UPDATE media_assets SET deleted_at=NULL,deleted_by=NULL,updated_at=NOW() WHERE id=? AND user_id=? AND deleted_at IS NOT NULL AND name<>?');$q->execute([$id,$uid,'.folder-marker']);if(!$q->rowCount()){$msg='Trashed item could not be restored.';$msgType='error';}else{$db->prepare("INSERT INTO media_audit_events(user_id,action,resource_type,resource_id,created_at) VALUES(?,?,?,?,NOW())")->execute([$uid,'RESTORE','media',$id]);$msg='Media restored.';}}}
        } elseif($a==='permanent_delete'){
            $id=(int)post('id');$q=$db->prepare('SELECT * FROM media_assets WHERE id=? AND user_id=? AND deleted_at IS NOT NULL AND name<>?');$q->execute([$id,$uid,'.folder-marker']);$m=$q->fetch();
            if(!$m){$msg='Trashed item not found.';$msgType='error';}else{
                if(!empty($m['canonical_file_id'])){$refs=$db->prepare('SELECT COUNT(*) FROM media_assets WHERE user_id=? AND canonical_file_id=? AND id<>?');$refs->execute([$uid,(int)$m['canonical_file_id'],$id]);$shareRefs=$db->prepare('SELECT COUNT(*) FROM file_share_items WHERE file_id=?');$shareRefs->execute([(int)$m['canonical_file_id']]);if((int)$refs->fetchColumn()===0&&(int)$shareRefs->fetchColumn()===0){$fq=$db->prepare('SELECT * FROM file_objects WHERE id=? AND user_id=?');$fq->execute([(int)$m['canonical_file_id'],$uid]);$obj=$fq->fetch();if($obj){if(($obj['storage_driver']??'')==='local'){$fp=file_local_path($obj);if(is_file($fp))@unlink($fp);}$db->prepare("UPDATE file_objects SET status='deleted',updated_at=NOW() WHERE id=? AND user_id=?")->execute([(int)$obj['id'],$uid]);}}}
                elseif(!empty($m['storage_path'])&&str_starts_with((string)$m['storage_path'],'/uploads/media/')){$path=parse_url((string)$m['storage_path'],PHP_URL_PATH);$rootPath=realpath(__DIR__.'/../uploads/media/'.$uid);$full=realpath(__DIR__.'/..'.(string)$path);if($rootPath&&$full&&str_starts_with($full,$rootPath.DIRECTORY_SEPARATOR)&&is_file($full))@unlink($full);}
                $db->prepare('DELETE FROM media_assets WHERE id=? AND user_id=? AND deleted_at IS NOT NULL')->execute([$id,$uid]);$db->prepare("INSERT INTO media_audit_events(user_id,action,resource_type,resource_id,created_at) VALUES(?,?,?,?,NOW())")->execute([$uid,'PERMANENT_DELETE','media',$id]);$msg='Media permanently deleted.';
            }
