            $q=$db->prepare('SELECT * FROM media_assets WHERE user_id=? AND deleted_at IS NOT NULL AND name<>? ORDER BY id LIMIT 500');$q->execute([$uid,'.folder-marker']);$trashRows=$q->fetchAll();
            if(!$trashRows){$msg='Trash is already empty.';}else{$deleted=0;foreach($trashRows as $m){$id=(int)$m['id'];if(!empty($m['canonical_file_id'])){$refs=$db->prepare('SELECT COUNT(*) FROM media_assets WHERE canonical_file_id=? AND id<>?');$refs->execute([(int)$m['canonical_file_id'],$id]);$shareRefs=$db->prepare('SELECT COUNT(*) FROM file_share_items WHERE file_id=?');$shareRefs->execute([(int)$m['canonical_file_id']]);if((int)$refs->fetchColumn()===0&&(int)$shareRefs->fetchColumn()===0){$fq=$db->prepare('SELECT * FROM file_objects WHERE id=? AND user_id=?');$fq->execute([(int)$m['canonical_file_id'],$uid]);$obj=$fq->fetch();if($obj){if(($obj['storage_driver']??'')==='local'){$fp=file_local_path($obj);if(is_file($fp))@unlink($fp);}$db->prepare("UPDATE file_objects SET status='deleted',updated_at=NOW() WHERE id=? AND user_id=?")->execute([(int)$obj['id'],$uid]);}}}elseif(!empty($m['storage_path'])&&str_starts_with((string)$m['storage_path'],'/uploads/media/')){$path=parse_url((string)$m['storage_path'],PHP_URL_PATH);$rootPath=realpath(__DIR__.'/../uploads/media/'.$uid);$full=realpath(__DIR__.'/..'.(string)$path);if($rootPath&&$full&&str_starts_with($full,$rootPath.DIRECTORY_SEPARATOR)&&is_file($full))@unlink($full);}$db->prepare('DELETE FROM media_assets WHERE id=? AND user_id=? AND deleted_at IS NOT NULL')->execute([$id,$uid]);$deleted++;}$db->prepare("INSERT INTO media_audit_events(user_id,action,resource_type,metadata_json,created_at) VALUES(?,?,?,?,NOW())")->execute([$uid,'EMPTY_TRASH','media',json_encode(['count'=>$deleted])]);$msg='Trash emptied. '.$deleted.' item(s) permanently deleted.';}
        }
    }catch(Throwable $e){$msg='Media operation failed safely: '.($e->getMessage()?:'unknown server error').'.';$msgType='error';}
}

$folder=(string)getv('folder','');$q=trim((string)getv('q',''));$kind=(string)getv('kind','');$category=(string)getv('category','');$date=(string)getv('date','');$sort=(string)getv('sort','newest');$view=(string)getv('view','grid');$trashMode=$view==='trash';
$allowedCategories=[''=>'All sources','Media Assets'=>'Media Assets','Shared Files'=>'Shared Files','Support Attachments'=>'Support Attachments','AI Workspace'=>'AI Workspace'];if(!array_key_exists($category,$allowedCategories))$category='';
$allowedKinds=['image','video','audio','archive','file'];if(!in_array($kind,$allowedKinds,true))$kind='';
$allowedDates=['','today','7d','30d','90d','year'];if(!in_array($date,$allowedDates,true))$date='';
$sortSql=['newest'=>'created_at DESC','oldest'=>'created_at ASC','name'=>'name ASC','largest'=>'size_bytes DESC','favorites'=>'is_favorite DESC, created_at DESC'][$sort]??'created_at DESC';
$sql='SELECT m.*,f.id AS canonical_file_id,f.public_token AS file_public_token,f.object_key AS file_object_key,f.storage_driver AS file_storage_driver,f.provider_url AS file_provider_url,f.status AS file_status,f.scan_status AS file_scan_status FROM media_assets m LEFT JOIN file_objects f ON f.id=m.canonical_file_id AND f.user_id=m.user_id WHERE m.user_id=? AND m.name<>? AND '.($trashMode?'m.deleted_at IS NOT NULL':'m.deleted_at IS NULL');$params=[$uid,'.folder-marker'];
if($view==='favorites'){$sql.=' AND m.is_favorite=1';}if($folder!==''){$sql.=' AND m.folder_name=?';$params[]=$folder;}
if($kind!==''){$sql.=' AND m.kind=?';$params[]=$kind;}if($category!==''){$sql.=' AND m.source_category=?';$params[]=$category;}
if($q!==''){$sql.=' AND (m.name LIKE ? OR m.alt_text LIKE ? OR m.description LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}
if($date!==''){$days=['today'=>0,'7d'=>7,'30d'=>30,'90d'=>90,'year'=>365][$date];$sql.=$days===0?' AND m.created_at>=CURDATE()':' AND m.created_at>=DATE_SUB(NOW(),INTERVAL '.$days.' DAY)';}
$sortSql=str_replace(['created_at','name','size_bytes','is_favorite'],['m.created_at','m.name','m.size_bytes','m.is_favorite'],$sortSql);$sql.=' ORDER BY '.$sortSql.' LIMIT 500';$st=$db->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$st=$db->prepare("SELECT folder_name,SUM(name<>'.folder-marker' AND deleted_at IS NULL) n,MAX(name='.folder-marker') has_marker FROM media_assets WHERE user_id=? GROUP BY folder_name ORDER BY folder_name");$st->execute([$uid]);$folders=$st->fetchAll();$categoryCounts=array_fill_keys(array_keys($allowedCategories),0);$st=$db->prepare("SELECT source_category,COUNT(*) n FROM media_assets WHERE user_id=? AND name<>'.folder-marker' AND deleted_at IS NULL GROUP BY source_category");$st->execute([$uid]);foreach($st->fetchAll() as $cr){$key=(string)$cr['source_category'];if(isset($categoryCounts[$key]))$categoryCounts[$key]=(int)$cr['n'];}
$stats=['total'=>0,'image'=>0,'video'=>0,'audio'=>0,'file'=>0,'archive'=>0,'favorite'=>0];$sq=$db->prepare("SELECT kind,COUNT(*) n,SUM(is_favorite) fav FROM media_assets WHERE user_id=? AND name<>'.folder-marker' AND deleted_at IS NULL GROUP BY kind");$sq->execute([$uid]);foreach($sq as $r){$stats['total']+=(int)$r['n'];$k2=$r['kind'];if(isset($stats[$k2]))$stats[$k2]+=(int)$r['n'];$stats['favorite']+=(int)$r['fav'];}
