a-copy-url="<?=e($url)?>">Share / Copy URL</button><?php if(!empty($m['canonical_file_id'])&&!empty($m['file_public_token'])):?><button type="button" data-media-download>Direct download</button><?php else:?><a href="<?=e($url)?>" target="_blank" rel="noopener" download>Direct download</a><?php endif;?><button type="button" data-open-edit>Rename / Edit</button><button type="button" data-delete-media="<?=$m['id']?>">Delete</button></div></details><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="favorite"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="media-fav <?=$fav?'active':''?>" title="<?=$fav?'Remove favorite':'Add favorite'?>" aria-label="Favorite">★</button></form></div><small><?=e($m['source_category']??'Media Assets')?> · <?=e($m['folder_name']??'General')?> · <?=e(strtoupper($m['kind']??'file'))?> · <?=e($m['size_bytes']?storage_human((int)$m['size_bytes']):'Remote')?></small><?php if(!empty($m['width'])&&$m['height']):?><small><?=e($m['width'])?> × <?=e($m['height'])?> px</small><?php endif;?><div class="media-actions"><?php if(!empty($m['canonical_file_id'])):?><a class="edit-btn primary" href="/files/?highlight=<?=e((string)$m['canonical_file_id'])?>" data-open-media-file>Open in Files</a><?php endif;?><button class="edit-btn" type="button" data-copy-url="<?=e($url)?>">Copy URL</button><button class="edit-btn" type="button" data-media-info data-name="<?=e($m['name'])?>" data-folder="<?=e($m['folder_name'])?>" data-kind="<?=e($m['kind'])?>" data-size="<?=e((string)$m['size_bytes'])?>" data-mime="<?=e($m['mime_type'])?>" data-created="<?=e($m['created_at'])?>" data-updated="<?=e($m['updated_at'])?>" data-dimensions="<?=e(!empty($m['width'])&&$m['height']?$m['width'] . ' × ' . $m['height'] . ' px':'')?>">Info</button><button class="edit-btn" type="button" data-create-analytics="<?=$m['id']?>">Create Link &amp; Analytics</button><?php if(!empty($m['canonical_file_id'])&&!empty($m['file_public_token'])):?><button class="edit-btn" type="button" data-media-download>Download</button><?php else:?><a class="edit-btn" href="<?=e($url)?>" target="_blank" rel="noopener" download>Download</a><?php endif;?><?php if(in_array($m['kind'],['image','video','audio'],true)):?><button class="edit-btn" type="button" data-open-preview>Preview</button><?php endif;?><a class="edit-btn" href="<?=e($url)?>" target="_blank" rel="noopener" <?=str_starts_with($m['source_url'],'/uploads/')?'download':''?>>Open</a><?php if($trashMode):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="restore"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="edit-btn" type="submit">Restore</button></form><form method="post" data-confirm="Permanently delete this item? This cannot be undone."><?=csrf_field()?><input type="hidden" name="action" value="permanent_delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="edit-btn danger" type="submit">Delete permanently</button></form><?php else:?><form method="post" data-confirm="Move this media item to Trash? You can restore it later."><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="edit-btn danger" type="submit">Move to Trash</button></form><?php endif;?></div><details class="media-edit"><summary>Edit details</summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$m['id']?>"><label>Name<input name="name" value="<?=e($m['name'])?>" required></label><label>Folder<select name="folder"><?php foreach($folders as $f):?><option value="<?=e($f['folder_name'])?>" <?=$m['folder_name']===$f['folder_name']?'selected':''?>><?=e($f['folder_name'])?></option><?php endforeach;?></select></label><label>Alt text<input name="alt_text" value="<?=e($m['alt_text']??'')?>" placeholder="Useful description for images"></label><label>Description<textarea name="description" rows="3"><?=e($m['description']??'')?></textarea></label><label class="check"><input type="checkbox" name="is_favorite" value="1" <?=$fav?'checked':''?>> Favorite</label><button class="btn small">Save details</button></form></details></div></article><?php endforeach;if(!$rows):?><div class="card"><p class="muted">No media matched these filters.</p></div><?php endif;?></div>
