<script>
(function(){
 'use strict';
 function pcToast(message){let t=document.getElementById('pcMediaToast');if(!t){t=document.createElement('div');t.id='pcMediaToast';t.className='pc-toast';t.setAttribute('role','status');t.setAttribute('aria-live','polite');document.body.appendChild(t)}t.textContent=String(message||'');t.hidden=false;clearTimeout(t._timer);t._timer=setTimeout(()=>{t.hidden=true},6500)}
 function alert(message){pcToast(message)}
 function pcConfirm(message,title='Please confirm',yes='Continue'){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='pc-confirm-backdrop';wrap.innerHTML='<section class="pc-confirm-card" role="dialog" aria-modal="true" aria-labelledby="pcConfirmTitle"><h2 id="pcConfirmTitle"></h2><p></p><div class="pc-confirm-actions"><button type="button" class="btn secondary" data-no>Cancel</button><button type="button" class="btn danger" data-yes></button></div></section>';wrap.querySelector('h2').textContent=title;wrap.querySelector('p').textContent=message;wrap.querySelector('[data-yes]').textContent=yes;document.body.appendChild(wrap);const finish=v=>{wrap.remove();resolve(v)};wrap.querySelector('[data-no]').onclick=()=>finish(false);wrap.querySelector('[data-yes]').onclick=()=>finish(true);wrap.addEventListener('click',e=>{if(e.target===wrap)finish(false)});wrap.addEventListener('keydown',e=>{if(e.key==='Escape')finish(false)});wrap.querySelector('[data-yes]').focus()})}
 document.addEventListener('click',e=>{const current=e.target.closest('.asset-menu');document.querySelectorAll('.asset-menu[open]').forEach(menu=>{if(menu!==current)menu.removeAttribute('open')})});
 document.addEventListener('toggle',e=>{const menu=e.target;if(!menu.matches?.('.asset-menu')||!menu.open)return;document.querySelectorAll('.asset-menu[open]').forEach(other=>{if(other!==menu)other.removeAttribute('open')});const r=menu.getBoundingClientRect();menu.classList.toggle('flip-up',window.innerHeight-r.bottom<250&&r.top>180)},true);
 document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-confirm]');if(!f)return;e.preventDefault();if(await pcConfirm(f.dataset.confirm,'Confirm action','Continue')){f.removeAttribute('data-confirm');f.requestSubmit()}});
 document.getElementById('quickBulkDelete')?.addEventListener('click',async e=>{e.preventDefault();const n=document.querySelectorAll('.media-check:checked').length;if(!n){pcToast('Select at least one media item.');return}if(await pcConfirm('Move '+n+' selected media item(s) to Trash? You can restore them later.','Move to Trash','Move to Trash')){document.getElementById('bulkAction').value='bulk_delete';document.getElementById('bulkMediaForm').requestSubmit()}});
 const form=document.querySelector('#media-upload form.form-card'),
       p=document.getElementById('mediaFilesPicker'),
       folderPicker=document.getElementById('mediaFolderPicker'),
       chooseFolder=document.getElementById('chooseMediaFolder'),
       q=document.getElementById('mediaQueue'),
       drop=document.getElementById('mediaDrop'),
       metrics=document.getElementById('mediaUploadMetrics'),
       submit=form?.querySelector('button[type="submit"]');
 if(!form||!p||!q)return;
 const csrf=form.querySelector('input[name="_csrf"]')?.value||window.POCKETCAT_CSRF||'';
 const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
 const bytes=n=>{
   n=Math.max(0,Number(n)||0);
   if(n<1024)return n.toFixed(0)+' B';
   const u=['KB','MB','GB','TB']; let v=n/1024,i=0;
   while(v>=1024&&i<u.length-1){v/=1024;i++}
   return v.toFixed(v>=100?0:v>=10?1:2)+' '+u[i];
 };
 const speedText=n=>(Number(n)>0?bytes(n)+'/s':'—');
 const etaText=(sec)=>{
   if(!Number.isFinite(sec)||sec<0)return 'Calculating…';
   const s=Math.ceil(sec); if(s<60)return s+'s';
   const m=Math.floor(s/60),r=s%60; if(m<60)return m+'m '+r+'s';
   return Math.floor(m/60)+'h '+(m%60)+'m';
 };
 let fs=[], states=new Map(), renderTimer=0, active=0, queueCursor=0;
 let MAX_CONCURRENT=2;
 const concurrencyPicker=document.getElementById('mediaUploadConcurrency');
 concurrencyPicker?.addEventListener('change',()=>{MAX_CONCURRENT=Math.max(2,Math.min(4,Number(concurrencyPicker.value)||2));pump();pcToast('Upload concurrency set to '+MAX_CONCURRENT+'.')});

 function sync(){
   // Keep the live upload cards mounted. The old implementation cleared the queue container
   // during every selection change, detaching progress cards from the DOM.
   try{const dt=new DataTransfer();fs.forEach(f=>dt.items.add(f));p.files=dt.files}catch(e){}
 }
 function updateMetrics(){
   const list=[...states.values()];
   const live=list.filter(s=>['uploading','retrying','preparing'].includes(s.phase));
   const total=list.reduce((n,s)=>n+s.total,0), uploaded=list.reduce((n,s)=>n+Math.min(s.total,s.uploaded),0);
   const now=performance.now();
   const net=live.reduce((n,s)=>n+(now-(s.lastProgressAt||now)<=2000?(s.lastSpeed||s.speed||0):0),0);
   const pct=total?Math.min(100,uploaded/total*100):0;
   if(metrics){
     metrics.hidden=!list.length;
     metrics.querySelector('[data-media-metric="progress"]').textContent=pct.toFixed(pct<10?1:0)+'% / 100%';metrics.querySelector('[data-media-global-progress]').style.width=pct.toFixed(2)+'%';
     metrics.querySelector('[data-media-metric="size"]').textContent=bytes(uploaded)+' / '+bytes(total);
     metrics.querySelector('[data-media-metric="speed"]').textContent=speedText(net);
     metrics.querySelector('[data-media-metric="files"]').textContent=list.filter(s=>s.phase==='done').length+' / '+list.length;
     const etaBytes=list.reduce((n,s)=>n+Math.max(0,s.total-s.uploaded),0);metrics.querySelector('[data-media-metric="eta"]').textContent=net>0?etaText(etaBytes/net):'—';
     metrics.querySelector('[data-media-metric="queue"]').textContent=list.filter(s=>s.running&&!s.paused&&!['done','error','cancelled'].includes(s.phase)).length+' active · '+list.filter(s=>s.phase==='queued').length+' queued · '+list.filter(s=>s.paused||s.phase==='paused').length+' paused';
   }
   let actions=document.getElementById('mediaUploadBatchActions');
   if(!actions&&metrics){
     actions=document.createElement('div');actions.id='mediaUploadBatchActions';actions.className='upload-batch-actions';
     actions.innerHTML='<label class="upload-select-all"><input type="checkbox" class="media-upload-select-all"> Select all</label><button type="button" class="btn small media-pause-selected">Pause selected</button><button type="button" class="btn small secondary media-resume-selected">Resume selected</button><button type="button" class="btn small secondary media-cancel-selected">Cancel selected</button><button type="button" class="btn small media-retry-all">Retry selected</button><button type="button" class="btn small danger media-remove-selected">Remove selected</button><button type="button" class="btn small secondary media-cancel-all">Cancel active uploads</button><button type="button" class="btn small secondary media-clear-failed">Clear cancelled / failed</button>';
     actions.querySelector('.media-pause-selected').onclick=()=>selectedStates().forEach(pause);actions.querySelector('.media-resume-selected').onclick=()=>selectedStates().forEach(resume);actions.querySelector('.media-cancel-selected').onclick=()=>selectedStates().forEach(cancel);actions.querySelector('.media-remove-selected').onclick=()=>selectedStates().forEach(dismiss);actions.querySelector('.media-upload-select-all').onchange=e=>{[...states.values()].forEach(s=>{const cb=s.card.querySelector('.upload-select');if(cb)cb.checked=e.target.checked});updateMetrics()}; 
     metrics.after(actions);
     actions.querySelector('.media-retry-all').onclick=()=>selectedStates().filter(s=>['error','cancelled','missing'].includes(s.phase)).forEach(s=>enqueue(s,true));
     actions.querySelector('.media-cancel-all').onclick=()=>[...states.values()].filter(s=>['queued','preparing','uploading','retrying','paused'].includes(s.phase)).forEach(cancel);
     actions.querySelector('.media-clear-failed').onclick=async()=>{if(!await pcConfirm('Remove all cancelled and failed upload entries?','Clear upload history','Remove entries'))return;[...states.values()].filter(s=>['error','cancelled','missing'].includes(s.phase)).forEach(dismiss);updateMetrics()};
   }
   if(actions){
     const failed=list.filter(s=>s.phase==='error'||s.phase==='cancelled'||s.phase==='missing').length;
     const cancellable=list.filter(s=>['queued','preparing','uploading','retrying','paused'].includes(s.phase)).length;
     actions.hidden=!list.length;actions.querySelector('.media-retry-all').disabled=!failed;actions.querySelector('.media-cancel-all').disabled=!cancellable;actions.querySelector('.media-clear-failed').disabled=!failed;actions.querySelector('.media-pause-selected').disabled=!selectedStates().some(s=>s.running&&!s.paused);actions.querySelector('.media-resume-selected').disabled=!selectedStates().some(s=>s.paused);actions.querySelector('.media-cancel-selected').disabled=!selectedStates().some(s=>!['done','cancelled'].includes(s.phase));actions.querySelector('.media-remove-selected').disabled=!selectedStates().length;actions.querySelector('.media-retry-all').disabled=!selectedStates().some(s=>['error','cancelled','missing'].includes(s.phase));
   }
 }
 function uploadIcon(f){const n=(f.name||'').toLowerCase(),t=f.type||'';if(t.startsWith('image/'))return '🖼️';if(t.startsWith('video/'))return '🎬';if(t.startsWith('audio/'))return '🎵';if(/\.(zip|rar|7z|tar|gz|bz2|xz)$/i.test(n))return '🗜️';if(/\.apk$/i.test(n))return '📦';if(/\.pdf$/i.test(n))return '📕';if(/\.(doc|docx|odt|rtf)$/i.test(n))return '📘';if(/\.(xls|xlsx|csv|ods)$/i.test(n))return '📗';if(/\.(ppt|pptx|odp)$/i.test(n))return '📙';return '📄'}
 function card(f){
   const d=document.createElement('div');d.className='upload-card card';
   d.innerHTML='<div class="upload-head"><label class="upload-select-label"><input type="checkbox" class="upload-select" aria-label="Select upload"></label><span class="upload-file-icon" aria-hidden="true">'+uploadIcon(f)+'</span><div class="upload-title-wrap"><b class="upload-name"></b><span class="upload-path"></span></div><span class="status">Queued…</span></div>'+
     '<div class="media-upload-size"><span>Upload size</span><strong class="upload-size">'+esc(bytes(f.size))+'</strong></div>'+
     '<div class="upload-progress-track"><i></i></div>'+
     '<div class="upload-metrics"><span class="upload-bytes">0 B / '+esc(bytes(f.size))+'</span><span class="upload-percent">0% / 100%</span><span class="upload-speed">—</span><span class="upload-eta">Calculating…</span></div><div class="upload-actions"></div>';
   d.querySelector('.upload-name').textContent=f.name;d.querySelector('.upload-path').textContent=f.webkitRelativePath||'';q.appendChild(d);return d;
 }
 function setStatus(s,text){s.card.querySelector('.status').textContent=text;s.card.dataset.state=s.phase}
 function updateCard(s){
   const now=performance.now(),uploaded=Math.min(s.total,Math.max(0,s.uploaded));
   const dt=Math.max(.001,(now-s.speedBaseTime)/1000),db=uploaded-s.speedBaseBytes;
   if(db>0)s.speed=db/dt;s.lastSpeed=s.speed||s.lastSpeed||0;
   if(now-(s.lastProgressAt||now)>2000)s.lastSpeed=0;
   const pct=s.total?Math.min(100,uploaded/s.total*100):0,eta=s.lastSpeed>0?(s.total-uploaded)/s.lastSpeed:Infinity;
   s.card.querySelector('.upload-progress-track i').style.width=pct.toFixed(2)+'%';
   s.card.querySelector('.upload-bytes').textContent=bytes(uploaded)+' / '+bytes(s.total);
   s.card.querySelector('.upload-percent').textContent=pct.toFixed(pct<10?1:0)+'% / 100%';
   s.card.querySelector('.upload-speed').textContent='Network speed: '+speedText(s.lastSpeed);
   s.card.querySelector('.upload-eta').textContent='ETA: '+(uploaded>=s.total?'Complete':etaText(eta));
   s.card.querySelector('.upload-size').textContent=bytes(s.total);
   if(now-s.speedBaseTime>=400){s.speedBaseBytes=uploaded;s.speedBaseTime=now}
   updateMetrics();
 }
 function actions(s,mode){
   const box=s.card.querySelector('.upload-actions');
   if(mode==='cancel')box.innerHTML=(s.paused?'<button type="button" class="btn small upload-resume">▶ Resume</button>':'<button type="button" class="btn small secondary upload-pause">Ⅱ Pause</button>')+'<button type="button" class="btn small secondary upload-cancel">Cancel</button><button type="button" class="btn small secondary upload-dismiss">Remove</button>';
   else if(mode==='retry')box.innerHTML='<button type="button" class="btn small upload-retry">Retry upload</button><button type="button" class="btn small secondary upload-dismiss">Remove</button>';
   else if(mode==='missing')box.innerHTML='<label class="btn small upload-reselect-label">Re-select File<input type="file" class="upload-reselect" hidden></label><button type="button" class="btn small secondary upload-dismiss">Remove</button>';
   else if(mode==='done')box.innerHTML='<span class="upload-complete-badge">✓ Completed</span><button type="button" class="btn small secondary upload-dismiss">Remove</button>';
   else box.innerHTML='';
   box.querySelector('.upload-pause')?.addEventListener('click',()=>pause(s));box.querySelector('.upload-resume')?.addEventListener('click',()=>resume(s));
   box.querySelector('.upload-cancel')?.addEventListener('click',()=>cancel(s));box.querySelector('.upload-retry')?.addEventListener('click',()=>enqueue(s,true));box.querySelector('.upload-dismiss')?.addEventListener('click',()=>dismiss(s));
   box.querySelector('.upload-reselect')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;const old=s.file;fs=fs.filter(x=>x!==old);s.file=f;s.total=Number(f.size);s.uploaded=0;s.token='';s.phase='queued';s.paused=false;s.cancelled=false;s.error='';s.card.querySelector('.upload-name').textContent=f.name;s.card.querySelector('.upload-path').textContent=f.webkitRelativePath||'';s.card.querySelector('.upload-file-icon').textContent=uploadIcon(f);s.card.classList.remove('upload-error');s.card.querySelector('.upload-error-message')?.remove();s.card.querySelector('.upload-missing-warning')?.remove();enqueue(s,false);sync()});
 }
 async function json(r){const text=await r.text();let j={};try{j=JSON.parse(text)}catch(e){}if(!r.ok||j.ok===false)throw Error(j.error||('Upload failed (HTTP '+r.status+')')+(j.request_id?' ['+j.request_id+']':''));return j}
 async function post(fd){const controller=new AbortController(),timeout=window.setTimeout(()=>controller.abort(),30000);try{return await json(await fetch('/api/upload-chunk/',{method:'POST',body:fd,credentials:'same-origin',headers:{Accept:'application/json'},signal:controller.signal}))}finally{window.clearTimeout(timeout)}}
 async function api(action,data={}){const fd=new FormData();fd.append('_csrf',csrf);fd.append('action',action);Object.entries(data).forEach(([k,v])=>fd.append(k,String(v)));return post(fd)}
 function xhrChunk(s,offset,chunkFile){
   return new Promise((resolve,reject)=>{
     const xhr=new XMLHttpRequest();s.xhr=xhr;let settled=false,started=performance.now(),stallTimer=0;
     const clearStall=()=>{if(stallTimer){window.clearTimeout(stallTimer);stallTimer=0}};
     const armStall=()=>{clearStall();if(!settled)stallTimer=window.setTimeout(()=>{if(!settled)xhr.abort()},20000)};
     const finish=(fn,v)=>{if(settled)return;settled=true;clearStall();if(s.xhr===xhr)s.xhr=null;fn(v)};
     xhr.open('POST','/api/upload-chunk/',true);xhr.setRequestHeader('Accept','application/json');
     const fd=new FormData();fd.append('_csrf',csrf);fd.append('action','chunk');fd.append('token',s.token);fd.append('offset',String(offset));fd.append('chunk',chunkFile,s.file.name+'.part');
     xhr.upload.onprogress=e=>{armStall();if(!e.lengthComputable)return;const now=performance.now(),elapsed=Math.max(.001,(now-started)/1000);s.uploaded=Math.min(s.total,offset+e.loaded);s.lastSpeed=e.loaded/elapsed;s.lastProgressAt=now;updateCard(s)};
     xhr.upload.onload=clearStall;
     xhr.onload=()=>{let j={};try{j=xhr.responseText?JSON.parse(xhr.responseText):{}}catch(e){}if(xhr.status>=200&&xhr.status<300&&j.ok!==false)return finish(resolve,j);const err=Error(j.error||('Upload failed (HTTP '+xhr.status+')')+(j.request_id?' ['+j.request_id+']':''));err.status=xhr.status;finish(reject,err)};
     xhr.onerror=()=>finish(reject,Error('Network error while uploading.'));xhr.ontimeout=()=>finish(reject,Error('Upload request timed out. Check the network connection and retry.'));xhr.onabort=()=>finish(reject,Error(s.cancelled?'Upload cancelled.':'Upload stalled or was aborted; retrying the current chunk.'));xhr.timeout=90000;armStall();xhr.send(fd);
   });
 }
 async function initSession(s,folder){const x=await api('init',{scope:'media',context_id:0,name:s.file.name,size:s.file.size,mime:s.file.type||'application/octet-stream',relative_path:s.file.webkitRelativePath||s.file.name,folder});s.token=x.token;s.chunkSize=Math.max(131072,Math.min(262144,Number(x.chunk_size||262144)));s.name=x.name||s.file.name;s.card.querySelector('.upload-name').textContent=s.name;return x}
 async function abortSession(token){if(!token)return;try{await api('abort',{token})}catch(e){}}
 async function wait(ms){return new Promise(r=>setTimeout(r,ms))}
 async function waitOnline(s){while(!navigator.onLine&&!s.cancelled){s.phase='retrying';setStatus(s,'Waiting for Network…');updateMetrics();await wait(1000)}if(s.cancelled)throw Error('Upload cancelled.')}
 async function waitUnpaused(s){while(s.paused&&!s.cancelled){s.phase='paused';setStatus(s,'Paused');updateMetrics();await wait(250)}if(s.cancelled)throw Error('Upload cancelled.')}
 async function retryableRequest(fn,s){let attempt=0;while(true){await waitOnline(s);await waitUnpaused(s);if(s.cancelled)throw Error('Upload cancelled.');try{return await fn()}catch(e){if(s.paused)continue;if(s.cancelled)throw Error('Upload cancelled.');if([400,401,403,404,413,422].includes(Number(e.status))||/blocked by policy|invalid upload|file type is blocked/i.test(e.message||''))throw e;attempt++;const delay=[2000,5000,10000][Math.min(attempt-1,2)];s.phase='retrying';setStatus(s,navigator.onLine?'Auto-Retrying · attempt '+attempt+'…':'Waiting for Network…');updateMetrics();await wait(delay)}}}
 async function chunkUpload(s,folder){
   setStatus(s,'Starting upload…');await retryableRequest(()=>initSession(s,folder),s);let offset=0,chunk=s.chunkSize;
   setStatus(s,'Checking upload session…');const st=await retryableRequest(()=>api('status',{token:s.token}),s);offset=Number(st.received||0);s.uploaded=offset;updateCard(s);
   while(offset<s.total){await waitUnpaused(s);if(s.cancelled)throw Error('Upload cancelled.');const end=Math.min(s.total,offset+chunk);let result=null;
     setStatus(s,'Uploading chunk…');
     try{result=await retryableRequest(async()=>{try{return await xhrChunk(s,offset,s.file.slice(offset,end,s.file.type||'application/octet-stream'))}catch(err){if(s.token){try{const probe=await api('status',{token:s.token});const received=Number(probe.received||0);if(received>offset)return {received}}catch(_probe){}}throw err}},s)}catch(e){if(e.name==='NotReadableError'||/not readable|could not be read/i.test(e.message||''))throw Object.assign(Error('File Not Found: This file was deleted or moved from its original local directory.'),{missing:true});throw e}
     const next=Number(result.received||end);if(next<=offset)throw Error('Upload made no progress. Please retry.');offset=next;s.uploaded=offset;updateCard(s);setStatus(s,'Uploading '+Math.round(offset/s.total*100)+'%');
   }
   const folderBase=folder;const rp=(s.file.webkitRelativePath||s.file.name).replace(/\\/g,'/').split('/').filter(Boolean);const finalFolder=rp.length>1?folderBase+'/'+rp.slice(0,-1).join('/'):folderBase;
   return api('complete',{token:s.token,folder:finalFolder});
 }
 async function run(s,retry=false){
   if(s.running)return;s.running=true;s.cancelled=false;s.paused=false;s.phase=retry?'retrying':'preparing';s.error='';s.card.classList.remove('upload-error','upload-success');actions(s,'cancel');
   if(!retry){s.uploaded=0;s.startedAt=performance.now()}s.speedBaseTime=performance.now();s.speedBaseBytes=s.uploaded;s.lastProgressAt=performance.now();s.lastSpeed=0;setStatus(s,retry?'Retrying upload…':'Preparing…');updateCard(s);
   try{const completed=await chunkUpload(s,form.querySelector('[name="folder"]')?.value||'General');s.mediaId=Number(completed.id||0);s.uploaded=s.total;s.phase='done';updateCard(s);setStatus(s,'Completed');s.card.classList.add('upload-success');actions(s,'done');insertUploadedAsset(completed,s);toast('✅ '+(completed.name||s.file.name)+' uploaded successfully');setTimeout(()=>{if(states.has(s.id)&&s.phase==='done')dismiss(s)},2500);}
   catch(err){if(s.cancelled){s.phase='cancelled';setStatus(s,'Cancelled');actions(s,'retry')}else if(s.paused){s.phase='paused';setStatus(s,'Paused');actions(s,'cancel')}else if(err.missing){s.phase='missing';s.error=err.message;s.card.classList.add('upload-error');setStatus(s,'File Missing');showMissingWarning(s,err.message);actions(s,'missing')}else{s.phase='error';s.error=err.message||'Upload failed.';s.card.classList.add('upload-error');setStatus(s,'Failed');let errBox=s.card.querySelector('.upload-error-message');if(!errBox){errBox=document.createElement('div');errBox.className='upload-error-message';s.card.insertBefore(errBox,s.card.querySelector('.upload-actions'))}errBox.textContent=s.error;actions(s,'retry')}}
   finally{s.running=false;active=Math.max(0,active-1);pump();updateMetrics()}
 }
 function enqueue(s,retry=false){if(s.phase==='done'||s.running)return;s.cancelled=false;s.paused=false;s.retryRequested=retry;s.phase='queued';s.card.classList.remove('upload-error');setStatus(s,retry?'Queued for retry…':'Queued…');actions(s,'cancel');pump();updateMetrics()}
 function pause(s){if(!s||s.phase==='done'||s.phase==='cancelled'||s.paused)return;s.paused=true;s.phase='paused';setStatus(s,'Pausing…');try{s.xhr?.abort()}catch(e){}actions(s,'cancel');updateMetrics()}
 function resume(s){if(!s||!s.paused)return;s.paused=false;if(!s.running){s.phase='queued';s.retryRequested=true;pump()}else{setStatus(s,'Resuming…');actions(s,'cancel')}updateMetrics()}
 function cancel(s){if(!s||s.phase==='done'||s.phase==='cancelled')return;s.cancelled=true;s.paused=false;s.phase='cancelled';setStatus(s,'Cancelling…');try{s.xhr?.abort()}catch(e){}const token=s.token;s.token='';if(token)abortSession(token);if(!s.running){s.uploaded=0;setStatus(s,'Cancelled');actions(s,'retry')}updateMetrics()}
 function dismiss(s){if(!s)return;if(s.running){s.cancelled=true;s.paused=false;try{s.xhr?.abort()}catch(e){}if(s.token)abortSession(s.token)}states.delete(s.id);fs=fs.filter(f=>f!==s.file);s.card?.remove();sync();updateMetrics()}
 function selectedStates(){return [...states.values()].filter(s=>s.card?.querySelector('.upload-select')?.checked)}
 function showMissingWarning(s,msg){let b=s.card.querySelector('.upload-missing-warning');if(!b){b=document.createElement('div');b.className='upload-missing-warning';s.card.insertBefore(b,s.card.querySelector('.upload-actions'))}b.textContent=msg}
 function toast(message){const t=document.getElementById('mediaUploadToast');if(!t)return;t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{t.hidden=true},5000)}
 function insertUploadedAsset(asset,s){const grid=document.getElementById('media-grid');if(!grid||!asset?.id)return;const id=String(asset.id);if(document.getElementById('media-'+id))return;const card=document.createElement('article');card.className='media-card';card.id='media-'+id;card.dataset.kind=asset.kind||'file';card.dataset.fileId=String(asset.file_id||'');card.dataset.name=asset.name||s.file.name;card.dataset.folder=asset.folder||'General';card.dataset.size=String(s.total);card.dataset.mime=s.file.type||'application/octet-stream';const preview=document.createElement('div');preview.className='media-preview';preview.dataset.previewKind=card.dataset.kind;if(card.dataset.kind==='image'){const im=document.createElement('img');im.src=asset.url;im.alt=asset.name||s.file.name;im.loading='lazy';im.dataset.previewUrl=asset.url;preview.appendChild(im)}else if(card.dataset.kind==='video'){const v=document.createElement('video');v.src=asset.url;v.preload='metadata';v.controls=true;preview.appendChild(v)}else{const icon=document.createElement('div');icon.className='file-icon';icon.textContent=({archive:'🗜️',audio:'🎵'})[card.dataset.kind]||(/\.apk$/i.test(card.dataset.name)?'📦':/\.pdf$/i.test(card.dataset.name)?'📕':'📄');preview.appendChild(icon)}const body=document.createElement('div');body.className='media-card-body';const title=document.createElement('div');title.className='media-title-row';const strong=document.createElement('strong');strong.textContent=card.dataset.name;title.appendChild(strong);body.appendChild(title);const meta=document.createElement('small');meta.textContent='Media Assets · '+card.dataset.folder+' · '+String(card.dataset.kind).toUpperCase()+' · '+bytes(s.total);body.appendChild(meta);const acts=document.createElement('div');acts.className='media-actions';const copy=document.createElement('button');copy.type='button';copy.className='edit-btn';copy.textContent='Copy URL';copy.dataset.copyUrl=asset.url;copy.onclick=async()=>{try{await navigator.clipboard.writeText(asset.url);copy.textContent='Copied'}catch(e){window.prompt('Copy public URL',asset.url)}};acts.appendChild(copy);const open=document.createElement('a');open.className='edit-btn';open.href=asset.url;open.target='_blank';open.rel='noopener';open.textContent='Open';acts.appendChild(open);body.appendChild(acts);const selectWrap=document.createElement('div');selectWrap.className='media-select';const select=document.createElement('input');select.type='checkbox';select.className='media-check';select.name='ids[]';select.setAttribute('form','bulkMediaForm');select.value=id;select.dataset.url=asset.url;select.setAttribute('aria-label','Select '+card.dataset.name);selectWrap.appendChild(select);card.append(selectWrap,preview,body);grid.querySelector('.card:not(.media-card)')?.remove();grid.prepend(card);card.dataset.prefId=id;card.dataset.prefName=card.dataset.name;card.dataset.prefFolder=card.dataset.folder;card.dataset.prefSize=String(s.total);window.dispatchEvent(new CustomEvent('pocketcat:media-added',{detail:{id}}));const search=document.querySelector('.media-filter-form input[name="q"]');if(search&&search.value)card.hidden=!card.dataset.name.toLowerCase().includes(search.value.toLowerCase())}
 function makeState(f){const s={id:'mu-'+Date.now()+'-'+Math.random().toString(36).slice(2),file:f,total:Number(f.size),uploaded:0,phase:'queued',card:null,running:false,cancelled:false,paused:false,token:'',chunkSize:262144,speed:0,lastSpeed:0,speedBaseBytes:0,speedBaseTime:performance.now(),startedAt:performance.now(),lastProgressAt:performance.now(),error:'',retryRequested:false};s.card=card(f);states.set(s.id,s);setStatus(s,'Queued…');actions(s,'cancel');return s}
 function pump(){while(active<MAX_CONCURRENT){const next=[...states.values()].find(s=>s.phase==='queued'&&!s.running);if(!next)break;active++;run(next,!!next.retryRequested)}updateMetrics()}
 function add(list){const files=[...list].filter(f=>f&&Number(f.size)>0);files.forEach(f=>{fs.push(f);makeState(f)});pickerValueReset();sync();updateMetrics()}
 function pickerValueReset(){try{p.value=''}catch(e){}}
