 async function droppedFiles(dt){const direct=[...(dt?.files||[])],items=[...(dt?.items||[])];if(!items.length)return direct;const out=[];async function walk(entry,path=''){if(!entry)return;if(entry.isFile){await new Promise(resolve=>entry.file(f=>{try{Object.defineProperty(f,'webkitRelativePath',{value:path+f.name,configurable:true})}catch(e){}out.push(f);resolve()},resolve));return}if(entry.isDirectory){const reader=entry.createReader();await new Promise(resolve=>{const read=()=>reader.readEntries(async entries=>{if(!entries.length)return resolve();for(const child of entries)await walk(child,path+entry.name+'/');read()},resolve);read()})}}for(const item of items){const entry=item.webkitGetAsEntry?.();if(entry)await walk(entry);else{const f=item.getAsFile?.();if(f)out.push(f)}}return out.length?out:direct}
 drop?.addEventListener('drop',async e=>add(await droppedFiles(e.dataTransfer)));
 q.addEventListener('change',e=>{if(e.target.matches('.upload-select'))updateMetrics()});
 form.addEventListener('submit',e=>{e.preventDefault();if(!fs.length){toast('Choose at least one file or folder.');return}if(![...states.values()].length)fs.forEach(makeState);submit.disabled=true;submit.textContent='Uploads running…';pump();const monitor=()=>{const list=[...states.values()];if(!list.some(s=>['queued','preparing','uploading','retrying'].includes(s.phase))){submit.disabled=false;submit.textContent='Upload selected';return}setTimeout(monitor,300)};monitor()});
 window.addEventListener('online',()=>{[...states.values()].filter(s=>s.phase==='retrying'&&!s.running).forEach(s=>enqueue(s,true));updateMetrics()});window.addEventListener('offline',()=>{[...states.values()].filter(s=>s.running&&!s.cancelled).forEach(s=>{setStatus(s,'Waiting for Network…');s.phase='retrying'});updateMetrics()});
