 document.querySelectorAll('[data-delete-media]').forEach(b=>b.addEventListener('click',async()=>{if(!await pcConfirm('Move this media item to Trash? You can restore it later.','Move to Trash','Move to Trash'))return;const f=document.createElement('form');f.method='post';f.style.display='none';f.innerHTML='<?=csrf_field()?>'+'<input type="hidden" name="action" value="delete">'+'<input type="hidden" name="id" value="'+b.dataset.deleteMedia+'">';document.body.appendChild(f);f.submit()}));
 async function downloadMediaCard(button){
   const card=button.closest('.media-card');const id=Number(card?.dataset.fileId||0);const token=card?.dataset.fileToken||'';
   if(!id||!token){alert('This item has no downloadable File Storage record. Use Open or the source URL instead.');return}
   const old=button.textContent;button.disabled=true;button.textContent='Preparing…';
   try{const r=await fetch('/api/files/?action=download_start',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':shareCsrf},body:JSON.stringify({id,token})});const j=await r.json().catch(()=>({}));if(!r.ok||!j.url)throw Error(j.error||'The file download could not be prepared.');
     const a=document.createElement('a');a.href=j.url;a.rel='noopener';a.download='';document.body.appendChild(a);a.click();a.remove();setTimeout(async()=>{try{const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token+String(id)));const nonce=Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('');navigator.sendBeacon('/api/files/?action=complete_download',new Blob([JSON.stringify({id,token,nonce})],{type:'application/json'}))}catch(_e){}},2000);button.textContent='Download started';setTimeout(()=>{button.textContent=old},1500);
   }catch(err){alert(err.message||'Download failed.');button.textContent=old}finally{button.disabled=false}
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-media-download]');if(b){e.preventDefault();downloadMediaCard(b)}});
 document.querySelectorAll('[data-copy-url]').forEach(b=>b.addEventListener('click',async()=>{const url=b.dataset.copyUrl;try{await navigator.clipboard.writeText(url);b.textContent='Copied';setTimeout(()=>b.textContent='Copy URL',1200)}catch(e){window.prompt('Copy public URL',url)}}));
 const all=document.getElementById('selectAll'),checks=new Proxy([],{get(_target,prop){const live=[...document.querySelectorAll('.media-check')];const value=live[prop];return typeof value==='function'?value.bind(live):value}});
 const bulkForm=document.getElementById('bulkMediaForm'),dupDialog=document.getElementById('mediaDuplicateDialog');let allowBulkSubmit=false;bulkForm?.addEventListener('submit',async e=>{if(allowBulkSubmit)return;if(['bulk_delete','bulk_restore'].includes(document.getElementById('bulkAction')?.value))return;const chosen=checks.filter(x=>x.checked).map(x=>x.closest('.media-card')).filter(Boolean);if(!chosen.length){e.preventDefault();alert('Select at least one item.');return}const target=document.getElementById('bulkFolder')?.value||'General';const action=document.getElementById('bulkAction')?.value||'bulk_move';const names=new Set([...document.querySelectorAll('.media-card')].filter(c=>c.dataset.folder===target&&!chosen.includes(c)).map(c=>c.dataset.name));let hasConflict=false;for(const c of chosen){if(action==='bulk_move'&&c.dataset.folder===target)continue;if(names.has(c.dataset.name))hasConflict=true;names.add(c.dataset.name)}if(!hasConflict)return;e.preventDefault();if(!dupDialog?.showModal){const answer=prompt('Duplicate handling: type cancel, skip, replace, or rename','skip');if(!['cancel','skip','replace','rename'].includes(answer))return;document.getElementById('conflictMode').value=answer;allowBulkSubmit=true;bulkForm.requestSubmit();return}const choice=await new Promise(resolve=>{const done=()=>{dupDialog.removeEventListener('close',done);resolve(dupDialog.returnValue||'cancel')};dupDialog.addEventListener('close',done,{once:true});dupDialog.showModal()});if(choice==='cancel')return;document.getElementById('conflictMode').value=choice;allowBulkSubmit=true;bulkForm.requestSubmit()});
 function syncBulkSelection(){const n=checks.filter(x=>x.checked).length;const label=document.getElementById('mediaSelectedCount');if(label)label.textContent=n+' item'+(n===1?'':'s')+' selected';if(all)all.indeterminate=n>0&&n<checks.length;if(all)all.checked=checks.length>0&&n===checks.length;}
 checks.forEach(x=>x.addEventListener('change',syncBulkSelection));all?.addEventListener('change',()=>{checks.forEach(x=>x.checked=all.checked);syncBulkSelection()});syncBulkSelection();
 // Touch long-press selects a media card without triggering preview/navigation.
 document.querySelectorAll('.media-card').forEach(card=>{let timer=0,triggered=false;card.addEventListener('touchstart',()=>{triggered=false;timer=setTimeout(()=>{const cb=card.querySelector('.media-check');if(cb){cb.checked=true;cb.dispatchEvent(new Event('change',{bubbles:true}));card.classList.add('selected');triggered=true;pcToast('Selected '+(card.dataset.name||'item'))}},500)},{passive:true});['touchend','touchcancel','touchmove'].forEach(ev=>card.addEventListener(ev,()=>clearTimeout(timer),{passive:true}));card.addEventListener('contextmenu',e=>{if(triggered)e.preventDefault()})});
 document.getElementById('downloadSelectedMedia')?.addEventListener('click',async()=>{const chosen=checks.filter(x=>x.checked);if(!chosen.length){alert('Select at least one media item.');return}const ids=chosen.map(x=>Number(x.closest('.media-card')?.dataset.fileId||0));if(ids.some(id=>!id)){alert('Some selected media are external URLs or are not linked to downloadable file records. Download those items individually, or select only media linked to Files.');return}const button=document.getElementById('downloadSelectedMedia'),status=document.getElementById('mediaBulkStatus');button.disabled=true;status.textContent='Preparing archive…';try{const r=await fetch('/api/files/?action=zip',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':shareCsrf},body:JSON.stringify({ids,mode:document.getElementById('mediaBulkMode').value,format:document.getElementById('mediaBulkFormat').value})});if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(j.error||'Bulk download failed')}const type=(r.headers.get('Content-Type')||'').toLowerCase();if(type.includes('text/html')||type.includes('application/json')){const body=await r.text();let message='The server returned a page instead of a downloadable archive.';try{message=JSON.parse(body).error||message}catch(_e){}throw Error(message)}const blob=await r.blob();if(!blob.size)throw Error('The server returned an empty archive.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const cd=r.headers.get('Content-Disposition')||'';const utf=cd.match(/filename\*=UTF-8''([^;]+)/i);const plain=cd.match(/filename="?([^";]+)"?/i);a.download=utf?decodeURIComponent(utf[1]):(plain?.[1]||'pocketcat-files.zip');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Download started.'}catch(e){status.textContent=e.message||'Download failed.'}finally{button.disabled=false}});
 document.getElementById('copySelected')?.addEventListener('click',async()=>{const urls=checks.filter(x=>x.checked).map(x=>x.dataset.url);if(!urls.length){alert('Select at least one media item.');return}const text=urls.join('\n');try{await navigator.clipboard.writeText(text);alert(urls.length+' URL(s) copied.')}catch(e){window.prompt('Copy selected URLs',text)}});
