 async function createShare(ids,mode,folders=[]){if(!ids.length&&!folders.length){alert('Select at least one file or folder.');return}const button=mode==='analytics'?document.getElementById('createBulkAnalytics'):document.getElementById('createExpiryLink');if(button){button.disabled=true;button.dataset.oldText=button.textContent;button.textContent='Creating…'}try{const r=await fetch('/api/media-share.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':shareCsrf},body:JSON.stringify({_csrf:shareCsrf,ids,folders,mode,expires:document.getElementById('mediaShareExpiry')?.value||'7d'})});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Unable to create share link');if(mode==='analytics'&&j.redirect){location.href=j.redirect;return}try{await navigator.clipboard.writeText(j.url);alert('Secure share link created and copied to clipboard. '+(j.expires_at?'Expires: '+j.expires_at:'This link does not expire.'))}catch(e){window.prompt('Copy secure share link',j.url)}}catch(e){alert(e.message||'Unable to create share link')}finally{if(button){button.disabled=false;button.textContent=button.dataset.oldText||button.textContent}}}
