 document.getElementById('createBulkAnalytics')?.addEventListener('click',()=>createShare(checks.filter(x=>x.checked).map(x=>Number(x.value)),'analytics',[...document.querySelectorAll('[data-share-folder]:checked')].map(x=>x.value)));
